text:
/* Styles for the donation notification type */
&.in-app-notification-donation {
  --title-text: var(--color-secondary-default);
  --button-background: linear-gradient(var(--color-purple-80), #571c87);
  --button-stroke: var(--color-secondary-pressed);
  --button-background-hover: var(--button-background);
  --button-background-active: var(--color-secondary-pressed);
  --button-focus-ring: var(--color-secondary-pressed);
  --button-text: var(--active-background-color);
  --container-background: linear-gradient(135deg, var(--color-teal-50), var(--color-purple-80));
  --icon-url: url("chrome://messenger/skin/illustrations/in-app-notification-heart.svg");
  --icon-fill: var(--color-red-30);
  --icon-stroke: var(--color-red-60);

  padding: 1px;

  & .in-app-notification-content::before {
    content: "";
    position: absolute;
    inset: 0;
    background-color: light-dark(var(--color-white), var(--color-gray-90));
    background-image: var(--illustration);
    background-size: calc(100% + 2px); /* This accounts for the border */
    background-position: bottom 0 left -1px;
    background-repeat: no-repeat;
    border-radius: 4px;
    z-index: -1;
  }
